import{_ as d,c as r,a as n,o}from"./index-B3LiEHuY.js";const s={};function e(a,t){return o(),r("section",null,[...t[0]||(t[0]=[n('<h2><span class="no">01</span>项目简介</h2><p>这是一个<strong>个人博客网站</strong>，包含一个对外展示的前台和一个管理内容的后台：</p><ul><li><strong>前台</strong>（所有人可见）：个人主页 + 博客列表 + 文章详情页，支持<strong>点赞</strong>与<strong>分享</strong></li><li><strong>后台</strong>（需登录）：写文章、编辑、发布/下架、删除，使用 <strong>wangEditor 富文本编辑器</strong>，可直接在文章里<strong>上传图片</strong></li></ul><h3>技术栈</h3><table><tr><th>层</th><th>技术</th><th>作用</th></tr><tr><td>前端</td><td>Vue 3 · Vite 6 · vue-router 4</td><td>页面渲染、路由跳转、构建打包</td></tr><tr><td>富文本</td><td>wangEditor 5</td><td>后台写文章时的所见即所得编辑器</td></tr><tr><td>后端</td><td>Go · Gin 框架</td><td>提供所有 API、登录鉴权、静态页面托管</td></tr><tr><td>数据库</td><td>MySQL 8</td><td>存储用户、文章、配置</td></tr><tr><td>认证</td><td>JWT + bcrypt</td><td>登录状态与密码安全</td></tr></table><h3>功能清单</h3><table><tr><th>功能</th><th>位置</th><th>说明</th></tr><tr><td>个人主页展示</td><td>前台 /</td><td>头像、自我介绍、技能、项目展示</td></tr><tr><td>博客列表</td><td>前台 /blog</td><td>已发布文章分页展示</td></tr><tr><td>文章详情</td><td>前台 /blog/:id</td><td>富文本正文、点赞、分享</td></tr><tr><td>后台登录</td><td>/admin/login</td><td>账密登录，JWT 鉴权</td></tr><tr><td>文章管理</td><td>/admin</td><td>列表、发布/下架、编辑、删除</td></tr><tr><td>写文章</td><td>/admin/posts/new</td><td>wangEditor 富文本 + 图片上传 + 封面</td></tr></table>',7)])])}const l=d(s,[["render",e]]);export{l as default};
